/* From Uiverse.io by Yaya12085 - Tags: loading, loader, colorful */
.__UIV_SCOPE__ .loader,.__UIV_SCOPE__ .loader::before,.__UIV_SCOPE__ .loader::after {
  border-width: 2px;
  border-style: solid;
  border-radius: 10px;
  animation: rotate 5s linear infinite;
}

.__UIV_SCOPE__ .loader {
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  width: 40px;
  height: 40px;
  border-color: #5a4ff3;
}

.__UIV_SCOPE__ .loader::before,.__UIV_SCOPE__ .loader::after {
  position: absolute;
  content: "";
}

.__UIV_SCOPE__ .loader::before {
  border-color: #35a2d2;
  width: 110%;
  height: 110%;
  animation-delay: .5s
}

.__UIV_SCOPE__ .loader::after {
  border-color: #9c40fc;
  width: 120%;
  height: 120%;
  animation-delay: .10s;
}

@keyframes rotate {
  to {
    transform: rotate(360deg)
  }
}
